import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;import java.io.*;import java.nio.charset.StandardCharsets;class PublicExamplesTest{@Test void undirectedAndIdempotent(){Object g=TaskBinding.graph(3);assertEquals(Set.of(),TaskBinding.neighbors(g,2));TaskBinding.add(g,0,1);TaskBinding.add(g,0,1);assertTrue(TaskBinding.edge(g,0,1));assertTrue(TaskBinding.edge(g,1,0));assertEquals(Set.of(1),TaskBinding.neighbors(g,0));assertEquals(Set.of(0),TaskBinding.neighbors(g,1));TaskBinding.remove(g,0,1);TaskBinding.remove(g,0,1);assertFalse(TaskBinding.edge(g,0,1));assertFalse(TaskBinding.edge(g,1,0));}}
